-- Automatisch erzeugt von scripts/gen-events-seed.ts — nicht von Hand bearbeiten.
-- Übernimmt die 43 kuratierten Events aus lib/events.ts in die Tabelle.
-- Idempotent: erneutes Ausführen aktualisiert bestehende Zeilen anhand des slug.

on conflict (slug) do update set
  date        = excluded.date,
  sport       = excluded.sport,
  promotion   = excluded.promotion,
  title       = excluded.title,
  main        = excluded.main,
  fighter_a   = excluded.fighter_a,
  fighter_b   = excluded.fighter_b,
  venue       = excluded.venue,
  broadcaster = excluded.broadcaster,
  note        = excluded.note,
  undercard   = excluded.undercard,
  updated_at  = now();
